1	import { join, dirname } from 'node:path';
2	import { fileURLToPath, pathToFileURL } from 'node:url';
3	import { MIGRATION_FILE, migrationDirs, migrationActive, recordName, flowOf } from '../checks/helpers/active-migrations.mjs';
4	import { RENAMED_PACKS } from '../pack_loader/renamed-packs.mjs';
5	import { SETTINGS_FILE, SETTINGS_FILES, LEGACY_SETTINGS_FILE } from '../settings-file.mjs';
6	import { installedVersions, withInstalledVersions, LEGACY_STAMP_KEY } from '../installed-versions.mjs';
7	import { ENDPOINTS_KEY, LEGACY_ENDPOINTS_KEY } from '../checks/helpers/repo-context.mjs';
8	
9	// <corpus>/engine/migrations/ — records are addressed corpus-relative, because they
10	// no longer share one directory with this module: an engine record sits beside it,
11	// a pack's under that pack.
12	const corpusRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
13	
14	// Each migration lives in its own folder under the flow that owns it — an engine
15	// record beside this registry, a pack's under that pack — so a record can carry
16	// assets of its own and each flow can ship exactly its own set. The discovery
17	// surface — the roots, the folder listing, the recency predicate, and
18	// `migrationActive` — lives in the vendored engine lib
19	// (engine/checks/helpers/active-migrations.mjs) because pack CHECKS consult it and packs import
20	// only the engine surface (pack-independence); this registry re-exports it so
21	// canon-side callers keep one import home.
22	export { MIGRATION_FILE, migrationActive, recordName };
23	
24	// Structural discovery, like packs/ and skills/: every
25	// <flow>/migrations/<landed-date>-<slug>/migration.mjs is a spec. ALL records
26	// present load — the apply/backfill path is unconditional, and FETCHING decides
27	// relevance: a vendored consumer mount carries only the recent records
28	// (vendoring's recency window), while a dormant project baselining out of a
29	// fresh canon clone sees every record ever landed and applies what it needs.
30	// Each object carries its `dir` — the record's CORPUS-RELATIVE path, which both
31	// names the record and says which flow owns it.
32	export async function loadMigrations() {
33	  const out = [];
34	  for (const d of migrationDirs()) {
35	    const spec = (await import(pathToFileURL(join(corpusRoot, d, MIGRATION_FILE)).href)).default;
36	    const record = { dir: d, ...spec };
37	    // Validated at LOAD, so a retired field cannot reach a flow that would ignore it,
38	    // and a malformed apply-stage declaration cannot reach the flow that acts on it.
39	    assertNoAgenticNote(record);
40	    assertApplyStageDeclaration(record);
41	    out.push(record);
42	  }
43	  return out;
44	}
45	
46	// Read side — "prefer Y, fall back to X": the ordered list of acceptable paths
47	// for a canonical target (canonical first, then its legacy aliases). A tolerance
48	// point consults this instead of hardcoding its own LEGACY_* constant, so a
49	// rename is declared once here and every reader picks it up. Unknown targets
50	// resolve to just themselves.
51	export function resolvePath(migrations, canonical) {
52	  for (const m of migrations) {
53	    for (const a of m.aliases ?? []) {
54	      if (a.canonical === canonical) return [a.canonical, ...(a.legacy ?? [])];
55	    }
56	  }
57	  return [canonical];
58	}
59	
60	// Write side — "and rename X -> Y": for each alias whose legacy path still
61	// exists and whose canonical does not, move legacy -> canonical. `exists` and
62	// `move` are injected so the same logic drives a local checkout (sync fs) or a
63	// future API applier (async). Idempotent — a no-op once the rename is done.
64	export async function applyFileAliases(migration, { exists, move }) {
65	  const moved = [];
66	  for (const a of migration.aliases ?? []) {
67	    for (const legacy of a.legacy ?? []) {
68	      if ((await exists(legacy)) && !(await exists(a.canonical))) {
69	        await move(legacy, a.canonical);
70	        moved.push(`${legacy} -> ${a.canonical}`);
71	      }
72	    }
73	  }
74	  return moved;
75	}
76	
77	// Write side — "vendor these pack templates into the repo": for each declared
78	// materialization {template, dest}, copy the canon template to its destination
79	// when the dest is missing or has drifted from the template (idempotent; a
80	// hand-edited copy self-heals on the next pass). `readTemplate` reads from the
81	// canon (the pack tree / mounted .claudinite), `read`/`write` act on the consumer
82	// repo — the source and destination roots differ in a consumer, so they are
83	// distinct injected readers. Gated by the migration's `appliesTo` so it only
84	// touches repos that ship the pipeline (never the canon repo itself).
85	// A materialization whose dest is a WORKFLOW FILE can only be written by a caller that
86	// can get it delivered. The nightly converge pushes with the Action's GITHUB_TOKEN, which
87	// GitHub never lets write under `.github/workflows/`, and the refusal rejects the whole
88	// ref — so writing one into a tree that is about to be pushed by such a caller does not
89	// deliver a workflow, it fails the entire converge and everything else riding it.
90	//
91	// The capable caller announces itself with this variable. The pack update flow sets it
92	// when it can WITHHOLD those paths from its commit and hand them to the apply stage;
93	// anything else — an older vendored worker, a hand-run `node engine/migrations/apply.mjs`, CI —
94	// leaves it unset and the workflow materialization is skipped with a note.
95	//
96	// An ENV HANDSHAKE rather than a probe of the repo on disk, because what matters is what
97	// the RUNNING process can do and the disk cannot answer that: the vendor step earlier in
98	// the same cycle replaces the on-disk worker with the new one while the old code is still
99	// executing.
100	export const WITHHOLD_CAPABLE_ENV = 'CLAUDINITE_CAN_WITHHOLD_WORKFLOWS';
101	const WORKFLOW_DEST = '.github/workflows/';
102	export const callerCanDeliverWorkflows = (env = process.env) => env[WITHHOLD_CAPABLE_ENV] === '1';
103	
104	export async function applyMaterializations(migration, { readTemplate, read, write, env = process.env }) {
105	  if (!migration.materialize?.length) return [];
106	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
107	  const done = [];
108	  for (const { template, dest } of migration.materialize) {
109	    const content = await readTemplate(template);
110	    if (content == null) continue; // template missing (partial mount) — skip, never clobber with nothing
111	    if ((await read(dest)) === content) continue; // already vendored, unchanged
112	    if (dest.startsWith(WORKFLOW_DEST) && !callerCanDeliverWorkflows(env)) {
113	      // Reported rather than silent — a silent skip reads as "already current". A caller
114	      // that can withhold writes it on a later cycle.
115	      done.push(`SKIPPED ${dest} (workflow file; this caller cannot deliver one)`);
116	      continue;
117	    }
118	    await write(dest, content);
119	    done.push(`${dest} <- ${template}`);
120	  }
121	  return done;
122	}
123	
124	// Write side — "rewrite these refs in place": for each declared file, apply its
125	// replacements (only those still matching), writing back when anything changed.
126	// Idempotent — a no-op once nothing matches. Preserves the rest of the file, so
127	// per-repo tweaks the template can't carry (e.g. an uncommented build_env block)
128	// survive. Same `appliesTo` gate.
129	//
130	// A replacement is either LITERAL (`{ from, to }`) or a PATTERN
131	// (`{ pattern: /…/g, to }`) — the regex-first shape engine migrations are meant to
132	// take (DESIGN §2.3), for the changes where no literal is common across repos.
133	// The pattern must be global, because every replacement here means replace-ALL:
134	// a non-global regex would silently rewrite only the first occurrence and leave a
135	// half-migrated file that reads as migrated.
136	export async function applyRewrites(migration, { read, write }) {
137	  if (!migration.rewrite?.length) return [];
138	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
139	  const done = [];
140	  for (const { file, replace } of migration.rewrite) {
141	    const text = await read(file);
142	    if (text == null) continue;
143	    let next = text;
144	    for (const r of replace ?? []) {
145	      if (r.pattern !== undefined) {
146	        if (!(r.pattern instanceof RegExp) || !r.pattern.global) {
147	          throw new Error(`migration ${migration.id}: rewrite pattern for ${file} must be a global RegExp — a non-global one rewrites only the first match`);
148	        }
149	        next = next.replace(r.pattern, r.to);
150	      } else {
151	        next = next.split(r.from).join(r.to);
152	      }
153	    }
154	    if (next !== text) { await write(file, next); done.push(file); }
155	  }
156	  return done;
157	}
158	
159	// The declaration a pack-seeding op writes into. Fixed, not a parameter: this op
160	// declares PACKS, and a repo's declaration lives in exactly one file. A `file` knob
161	// would quietly make it a general JSON editor, which is a much larger thing to own.
162	//
163	// TWO NAMES WHILE THE RENAME DRAINS (#1252): a record runs on a member whose file may
164	// still be `.claudinite-checks.json`, and one that only knew the new name would write
165	// a SECOND declaration beside the real one — a settings file nothing reads, with the
166	// pack the record meant to seed in it. `declarationFile` asks the member which name
167	// it carries; every op below writes back to that same one.
168	export const DECLARATION = SETTINGS_FILE;
169	
170	async function declarationFile(read) {
171	  for (const name of SETTINGS_FILES) {
172	    if ((await read(name)) != null) return name;
173	  }
174	  return null;
175	}
176	
177	// Write side — "every member should now declare this pack": for each declared
178	// `{ id, config }`, add that pack to the member's `packs` when it is absent, and
179	// fill in a `config` the entry does not already carry. The op the other three could
180	// not express — `materialize` writes a whole template (it would clobber a per-repo
181	// declaration) and `rewrite` replaces literal text (declarations share no literal
182	// across repos) — and the shape a fleet-wide capability change actually has: a pack
183	// every member should run, whose parameters the canon knows and the member cannot
184	// derive.
185	//
186	// SEEDING, NEVER OVERRIDING. A pack the repo already declares keeps its entry, and a
187	// config it already carries is left exactly as it is: both are that repo's decisions,
188	// and a migration that reasserted them would fight the project every night. That
189	// makes the op idempotent by construction — a no-op once the entry is there.
190	//
191	// ORDER MATTERS AROUND IT. Declaring a pack whose code is not in the member's mount
192	// is a blocking `config` error there, so the caller must re-converge the mount after
193	// applying (baselining does; see its worker). This module only writes the file.
194	//
195	// It round-trips the file through JSON rather than editing settings as text, so the
196	// result is canonical 2-space settings with a trailing newline (what `--init` writes,
197	// and what every fleet declaration already is). Malformed JSON is left alone: the
198	// world runner reports it as the settings error it is, and a migration is not the
199	// place to guess at a repair. Same `appliesTo` gate as the other write ops.
200	export async function applyPackDeclarations(migration, { read, write }) {
201	  if (!migration.declarePacks?.length) return [];
202	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
203	  const file = await declarationFile(read);
204	  if (file == null) return [];                      // not a member — nothing to declare into
205	  const raw = await read(file);
206	  let config;
207	  try { config = JSON.parse(raw); } catch { return []; }
208	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
209	  const packs = Array.isArray(config.packs) ? [...config.packs] : [];
210	  const idOf = (e) => (typeof e === 'string' ? e : e?.id);
211	  const done = [];
212	  for (const { id, config: packConfig } of migration.declarePacks) {
213	    const at = packs.findIndex((e) => idOf(e) === id);
214	    if (at === -1) {
215	      packs.push(packConfig ? { id, config: packConfig } : id);
216	      done.push(`${file}: declared ${id}`);
217	      continue;
218	    }
219	    // Declared already: the only thing still owed is a config it never got.
220	    if (!packConfig) continue;
221	    const prior = typeof packs[at] === 'string' ? { id } : packs[at];
222	    if (prior.config) continue;                     // the repo's own parameters — untouched
223	    packs[at] = { ...prior, id, config: packConfig };
224	    done.push(`${file}: configured ${id}`);
225	  }
226	  if (done.length) await write(file, `${JSON.stringify({ ...config, packs }, null, 2)}\n`);
227	  return done;
228	}
229	
230	// Write side — "normalize this repo's local-pack declarations": rewrite every
231	// declared local pack to the canonical `local/<id>` token, from the bare id or the
232	// earlier `local_packs/<id>` form.
233	//
234	// A NAMED CODEMOD rather than a `rewrite`, because the decision needs the repo's
235	// own disk. `local_packs/<id>` → `local/<id>` is a pure pattern, but a BARE id is
236	// only a local pack if that repo has one by that name — and a bare id that names a
237	// canon pack must not be touched. No regex can tell those apart, so the record
238	// declares `normalizeLocalDeclarations: true` and the deterministic code ships with
239	// the engine (DESIGN §2.3's "rarely code"). It is one op with one meaning, not a
240	// general escape hatch for arbitrary code in a record.
241	//
242	// SEEDS NOTHING AND DROPS NOTHING: entry objects keep their config, answers and
243	// order; only the id token changes. Idempotent — a repo already on `local/` is a
244	// no-op — and it patches the parsed declaration back through JSON.stringify with
245	// the same 2-space shape every other declaration writer here uses.
246	export async function applyLocalDeclarationNormalization(migration, { read, write, exists }) {
247	  if (!migration.normalizeLocalDeclarations) return [];
248	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
249	  const file = await declarationFile(read);
250	  if (file == null) return [];
251	  const raw = await read(file);
252	  let config;
253	  try { config = JSON.parse(raw); } catch { return []; }
254	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
255	  if (!Array.isArray(config.packs)) return [];
256	
257	  const done = [];
258	  const packs = [];
259	  for (const entry of config.packs) {
260	    const id = typeof entry === 'string' ? entry : entry?.id;
261	    if (typeof id !== 'string' || id.startsWith(LOCAL_DECL)) { packs.push(entry); continue; }
262	    let bare = id.startsWith(LEGACY_LOCAL_DECL) ? id.slice(LEGACY_LOCAL_DECL.length) : null;
263	    if (bare === null) {
264	      // A bare id: local only if this repo actually carries that pack. Both mount
265	      // shapes are checked, because a repo mid-relocation may hold either.
266	      const isLocal = (await exists(`.claudinite/local/packs/${id}/pack.mjs`))
267	        || (await exists(`.claudinite/local_packs/${id}/pack.mjs`));
268	      if (!isLocal) { packs.push(entry); continue; }
269	      bare = id;
270	    }
271	    const token = `${LOCAL_DECL}${bare}`;
272	    packs.push(typeof entry === 'string' ? token : { ...entry, id: token });
273	    done.push(`${file}: ${id} -> ${token}`);
274	  }
275	  if (done.length) await write(file, `${JSON.stringify({ ...config, packs }, null, 2)}\n`);
276	  return done;
277	}
278	
279	// The declaration tokens this op normalizes to and from. Stated here rather than
280	// imported from the pack registry: this module is the write side a consumer runs
281	// out of its own mount, and the two prefixes are the whole of what it needs.
282	const LOCAL_DECL = 'local/';
283	const LEGACY_LOCAL_DECL = 'local_packs/';
284	
285	// Write side — "the packs this repo declares have been renamed": rewrite each
286	// `packs` entry whose id is a legacy spelling to the id that pack carries today.
287	// The ids come from the engine's own rename map, never from the record, so a future
288	// rename needs no new op and no record restating what the loader already knows.
289	//
290	// STRUCTURAL, NOT TEXTUAL, and that is the whole point of it. The first attempt at
291	// this was a regex over the declaration, anchored on `"packs": [` so it could not
292	// wander into a member's own `{ "from": "core" }` barrier rule. It could not wander
293	// anywhere at all: a real packs array holds entry objects with nested arrays
294	// (`{ "id": "barriers", "via": ["basics"] }`), the anchor could not cross a nested
295	// `]`, and every element after the first such object was invisible to it. Parsing
296	// removes both failures at once — the `packs` array is the only thing read, so a
297	// same-named key anywhere else in the file is never even seen (#1041).
298	//
299	// SEEDS NOTHING AND DROPS NOTHING, like the local-declaration normalization beside
300	// it: entry objects keep their config, answers, `via` and order; only the id token
301	// changes. A LOCAL declaration is skipped — that namespace is the repo's, so a local
302	// pack sharing a canon pack's old name is not this op's business. Idempotent, so a
303	// repo already converged is a no-op, and it patches the parsed declaration back with
304	// the same 2-space shape every other declaration writer here uses.
305	// Two entries that were different packs and are now the same one. A rename can
306	// merge two ids into one (a pack absorbed into another), and every member carrying
307	// the absorbed pack carries the absorbing one too when the first `requires` the
308	// second — so the collision is not an edge case there, it is every member.
309	//
310	// Dropping either side would drop what a member wrote: `config` answers it gave at
311	// adoption, `rules` severities it chose, `accept` entries standing against findings
312	// that would otherwise come back. So the two are MERGED. The survivor is the entry
313	// that appeared first, and its own values win a key conflict — the absorbed entry
314	// fills only what the survivor does not say. Arrays (`accept`, `rules`, `via`)
315	// concatenate, dropping an element the survivor already carries verbatim. An object
316	// absorbed into a plain-string entry promotes the survivor to an object: a string
317	// entry carries an id and nothing else, so keeping the string would be the one shape
318	// that silently discards the other side.
319	export function mergeDeclarationEntries(survivor, absorbed) {
320	  if (typeof absorbed === 'string') return survivor;
321	  const base = typeof survivor === 'string' ? { id: survivor } : { ...survivor };
322	  for (const [key, value] of Object.entries(absorbed)) {
323	    if (key === 'id') continue;
324	    const have = base[key];
325	    if (have === undefined) { base[key] = value; continue; }
326	    if (Array.isArray(have) && Array.isArray(value)) {
327	      const seen = new Set(have.map((v) => JSON.stringify(v)));
328	      base[key] = [...have, ...value.filter((v) => !seen.has(JSON.stringify(v)))];
329	      continue;
330	    }
331	    if (have && value && typeof have === 'object' && typeof value === 'object'
332	      && !Array.isArray(have) && !Array.isArray(value)) {
333	      base[key] = { ...value, ...have };
334	    }
335	    // Two scalars that disagree: the survivor's stands. It is the entry the member
336	    // wrote for the pack that still exists under its own name.
337	  }
338	  return base;
339	}
340	
341	export async function applyPackRenames(migration, { read, write }) {
342	  if (!migration.renameDeclaredPacks) return [];
343	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
344	  const file = await declarationFile(read);
345	  if (file == null) return [];
346	  const raw = await read(file);
347	  let config;
348	  try { config = JSON.parse(raw); } catch { return []; }
349	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
350	  if (!Array.isArray(config.packs)) return [];
351	
352	  const done = [];
353	  const renamed = config.packs.map((entry) => {
354	    const id = typeof entry === 'string' ? entry : entry?.id;
355	    if (typeof id !== 'string' || id.startsWith(LOCAL_DECL) || id.startsWith(LEGACY_LOCAL_DECL)) return entry;
356	    const to = RENAMED_PACKS[id];
357	    if (to === undefined) return entry;
358	    done.push(`${file}: ${id} -> ${to}`);
359	    return typeof entry === 'string' ? to : { ...entry, id: to };
360	  });
361	
362	  // Collapse what the rename made duplicates. Position is the first occurrence's,
363	  // so an id already in the array keeps its place rather than moving to where the
364	  // absorbed entry sat.
365	  const at = new Map();
366	  const packs = [];
367	  for (const entry of renamed) {
368	    const id = typeof entry === 'string' ? entry : entry?.id;
369	    if (typeof id !== 'string' || !at.has(id)) {
370	      if (typeof id === 'string') at.set(id, packs.length);
371	      packs.push(entry);
372	      continue;
373	    }
374	    const i = at.get(id);
375	    packs[i] = mergeDeclarationEntries(packs[i], entry);
376	    done.push(`${file}: merged a second "${id}" entry into the first`);
377	  }
378	
379	  if (done.length) await write(file, `${JSON.stringify({ ...config, packs }, null, 2)}\n`);
380	  return done;
381	}
382	
383	
384	// Write side — "this member's settings file moves to its new name and its new
385	// shape" (#1252). The one op that RENAMES the declaration, which is why it is an op
386	// rather than four `rewrite`s: a rewrite replaces literal text, and no two members
387	// share a literal here; a materialization writes a whole template, which would
388	// clobber every project's own declaration.
389	//
390	// What it does, in the order that keeps a half-applied run readable:
391	//   1. moves `.claudinite-checks.json` to `.claudinite-settings.json` (git sees a
392	//      rename, so the file's history follows it);
393	//   2. lifts the retired `claudinite` block's `engineVersion` to the top level and
394	//      its `packVersions` onto the entry of each pack they price, dropping any key
395	//      no entry names — a version for a pack the declaration does not carry prices
396	//      nothing, and inventing an entry for it would activate a pack nobody declared;
397	//   3. turns `maintenance.delivery: review` into
398	//      `dailyClaudiniteUpdatesRequirePrReview: true` and drops the block — including
399	//      `mechanism`, whose only rival was deleted in #768 Phase 5, so it had exactly
400	//      one possible answer for every member that could still ask;
401	//   4. renames `taskScheduler.endpoints` to `agenticTaskInvocationEndpoints`.
402	//
403	// IDEMPOTENT BY CONSTRUCTION: every step is stated as "if the retired shape is
404	// there", so a second run finds nothing and writes nothing. It reads the member's
405	// OWN file and rewrites only the keys it names — a project's rules, accept entries,
406	// pack config and answers pass through untouched, and key ORDER is preserved for
407	// everything it does not move, because this is a file people read.
408	export async function applySettingsReshape(migration, { read, write, move, exists }) {
409	  if (!migration.reshapeSettings) return [];
410	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
411	  const file = await declarationFile(read);
412	  if (file == null) return [];
413	  const raw = await read(file);
414	  let config;
415	  try { config = JSON.parse(raw); } catch { return []; }
416	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
417	
418	  const done = [];
419	
420	  // 1. The name. Moved before anything is written, so the write below lands on the
421	  //    renamed file and git records one rename rather than a delete and an add.
422	  if (file === LEGACY_SETTINGS_FILE) {
423	    if (await exists(SETTINGS_FILE)) return [];     // both names present — a repair no record should guess at
424	    await move(LEGACY_SETTINGS_FILE, SETTINGS_FILE);
425	    done.push(`${LEGACY_SETTINGS_FILE} -> ${SETTINGS_FILE}`);
426	  }
427	
428	  // 2. The versions, onto the shape that holds them now.
429	  let next = config;
430	  if (next[LEGACY_STAMP_KEY] !== undefined) {
431	    const { engineVersion, packVersions } = installedVersions(next);
432	    next = withInstalledVersions(next, { engineVersion, packVersions });
433	    delete next[LEGACY_STAMP_KEY];
434	    done.push(`${SETTINGS_FILE}: engineVersion and per-pack versions lifted out of "${LEGACY_STAMP_KEY}"`);
435	  }
436	
437	  // 3. The delivery override. Only `review` carries an intent worth keeping; every
438	  //    other value said what the absent key now says.
439	  if (next.maintenance !== undefined) {
440	    const delivery = String(next.maintenance?.delivery ?? '').trim();
441	    const { maintenance, ...rest } = next;
442	    next = rest;
443	    if (delivery === 'review' || delivery === 'pr') {
444	      next.dailyClaudiniteUpdatesRequirePrReview = true;
445	      done.push(`${SETTINGS_FILE}: maintenance.delivery "${delivery}" -> dailyClaudiniteUpdatesRequirePrReview: true`);
446	    } else {
447	      done.push(`${SETTINGS_FILE}: dropped the retired "maintenance" block`);
448	    }
449	  }
450	
451	  // 4. The endpoint map's name.
452	  const scheduler = next.taskScheduler;
453	  if (scheduler && typeof scheduler === 'object' && !Array.isArray(scheduler)
454	      && scheduler[LEGACY_ENDPOINTS_KEY] !== undefined && scheduler[ENDPOINTS_KEY] === undefined) {
455	    const { [LEGACY_ENDPOINTS_KEY]: endpoints, ...restScheduler } = scheduler;
456	    next = { ...next, taskScheduler: { [ENDPOINTS_KEY]: endpoints, ...restScheduler } };
457	    done.push(`${SETTINGS_FILE}: taskScheduler.${LEGACY_ENDPOINTS_KEY} -> ${ENDPOINTS_KEY}`);
458	  }
459	
460	  if (done.length) await write(SETTINGS_FILE, `${JSON.stringify(next, null, 2)}\n`);
461	  return done;
462	}
463	
464	// EVERY write op a record can carry, in the order a run applies them, over one
465	// injected io. Both callers — the standalone applier and the engine update flow —
466	// go through this, so an op added to the vocabulary cannot reach one and miss the
467	// other: that omission is silent (the record simply does nothing on that path) and
468	// is exactly what a member would never notice.
469	export async function applyMigration(migration, io) {
470	  const applied = [];
471	  applied.push(...(await applyFileAliases(migration, io)));
472	  applied.push(...(await applyMaterializations(migration, io)));
473	  applied.push(...(await applyRewrites(migration, io)));
474	  applied.push(...(await applyPackDeclarations(migration, io)));
475	  applied.push(...(await applyLocalDeclarationNormalization(migration, io)));
476	  applied.push(...(await applyPackRenames(migration, io)));
477	  // LAST: every op above writes to whichever name the member still carries, and this
478	  // is the one that changes which name that is.
479	  applied.push(...(await applySettingsReshape(migration, io)));
480	  return applied;
481	}
482	
483	// THE `agentic` FIELD IS RETIRED (#768 Phase 5), and its successor is `applyStage`
484	// below. A record used to carry `agentic: { model, instructions }` — member-side
485	// adaptation no script could do — and baselining's code-work read it to decide whether
486	// a pending note needed an agent stage, holding the member's stamp until one ran.
487	//
488	// What the successor drops is the MODEL knob. Which model runs a session is the
489	// scheduler's answer (packs/claudinite-tasks/model-map.mjs, off the task declaration), and
490	// a record reaching around it to name its own was a second authority over the same
491	// fact. What a record legitimately knows is narrower and is all `applyStage` asks
492	// for: whether its change needs a session at all, and what that session must do.
493	//
494	// The field is not merely ignored, it is REJECTED. An ignored field on a record
495	// someone writes in good faith is work that silently never happens; the whole reason
496	// the note existed was that skipping such work quietly is a correctness risk (#405).
497	// Failing at load turns a stale or hopeful note into an error with a fix attached.
498	export function assertNoAgenticNote(m) {
499	  if (m?.agentic === undefined || m?.agentic === null) return;
500	  throw new Error(`migration ${m.id}: the "agentic" field was retired in #768 Phase 5 and is no longer run. `
501	    + 'Declare `applyStage: { why, instructions }` instead — same intent, without the model knob, which the '
502	    + 'scheduler owns. Engine records may not carry it at all (DESIGN §5); a pack record may.');
503	}
504	
505	// THE `applyStage` FIELD: this record's change needs a session on the member.
506	//
507	// It exists because the alternative was worse. The pack flow used to decide the
508	// apply stage from its VERSION PLAN — "any pack version moved" — which is a fact
509	// about the CANON, while the stage exists for a fact about the MEMBER: the pack's
510	// new rules met content the canon has never seen. Since a record can only reach an
511	// up-to-date member if its pack's manifest version bumps, and every bump fired the
512	// stage, a purely mechanical migration — a regex rewrite, a declaration seed — could
513	// not be shipped without spending an agent session on every member in the fleet
514	// (#798). The record's author knows which of the two kinds they wrote; a version
515	// number never can.
516	//
517	// SHAPE, VALIDATED AT LOAD for the same reason the retired field is rejected there:
518	// a record whose declaration is malformed must fail where it is written, not go
519	// quietly unread by the flow that would have acted on it.
520	//
521	//   - `why` (required, non-empty string) — what the session is for, in the PR and in
522	//     the log. The terminal vocabulary insists every non-green end be explainable
523	//     (updates/terminals.mjs), and this is the sentence for this one.
524	//   - `instructions` (optional string) — appended to the standing brief. The standing
525	//     brief is policy that holds for every apply stage; this is what only this record
526	//     knows, and without it the declaration would be a bare boolean that tells the
527	//     session nothing about the change that summoned it.
528	//
529	// ENGINE RECORDS MAY NOT CARRY IT. "No agentic work in the engine flow. Ever."
530	// (DESIGN §5) — and the flow is read off where the record LIVES, so this is checked
531	// against the same structural classifier and cannot be misdeclared.
532	export function assertApplyStageDeclaration(m) {
533	  const declared = m?.applyStage;
534	  if (declared === undefined || declared === null) return;
535	  const bad = (what) => { throw new Error(`migration ${m.id}: ${what}`); };
536	  if (m.dir && flowOf(m.dir).flow !== 'pack') {
537	    bad('only a PACK record may declare "applyStage" — the engine update flow has no agentic lane (DESIGN §5). '
538	      + 'If the change needs a session on each member, it belongs to the pack whose rules it changes.');
539	  }
540	  if (typeof declared !== 'object' || Array.isArray(declared)) {
541	    bad('"applyStage" must be an object `{ why, instructions }`, not a bare flag — a stage nobody can explain '
542	      + 'is one nobody will trust the next time it fires.');
543	  }
544	  if (typeof declared.why !== 'string' || declared.why.trim() === '') {
545	    bad('"applyStage.why" must be a non-empty string saying what the session is for; it is what the PR and the log report.');
546	  }
547	  if (declared.instructions !== undefined && typeof declared.instructions !== 'string') {
548	    bad('"applyStage.instructions" must be a string — it is appended verbatim to the apply-stage brief.');
549	  }
550	}
551	
